-- DB: qnfo-audit
-- Rollback: UPDATE roadmap_implementation SET status = CASE id WHEN 21 THEN 'not-built' ELSE 'partial' END, evidence = substr(evidence, 1, instr(evidence, ' | W2F-B 2026-11-05') - 1), verified_at = CASE id WHEN 21 THEN NULL ELSE '2026-11-05T01:40:00Z' END WHERE id IN (18, 19, 21) AND instr(evidence, ' | W2F-B 2026-11-05') > 0; DELETE FROM agent_issues WHERE (title LIKE 'ROADMAP-1: QNFO.INFRA ARCHIVE-MARKER-READ-2:%' OR title LIKE 'ROADMAP-1: QNFO.INFRA ARCHIVE-MARKER-READ-3:%' OR title LIKE 'ROADMAP-1: QNFO.INFRA UNBIND-LIVE-BINDING-1:%' OR title LIKE 'ROADMAP-1: QNFO.INFRA REPO-ARCHIVE-NEXT-1:%') AND status = 'open';
-- CAUSE-MAPPED: registers no metric.
-- spof-review: adds no worker, cron, D1 trigger, route or credential; it writes three ledger rows and four issue rows.

